let crowdPlayPending=false,crowdLoadError=false,crowdPriming=false;
function selectedCrowdActive(){return started&&playing&&!finished&&where(t)===3&&t>=marks.dream&&t<marks.dream+5.9;}
function selectedCrowdLevel(){return selectedCrowdActive()&&!muted?.20*ease((t-marks.dream)/.45)*(ballroomState().crowd/.42)*Number($('envVolume').value)/65:0;}
function primeSelectedCrowd(){const media=$('crowdAudio');if(!media?.getAttribute('src'))return;if(media.error){crowdLoadError=false;media.load();}if(media.dataset.primed==='true')return;media.dataset.primed='true';crowdPriming=true;media.volume=0;media.preservesPitch=true;media.playbackRate=effectivePlaybackRate();media.play().then(()=>{if(!selectedCrowdActive()){media.pause();media.currentTime=0;}}).catch(()=>{media.dataset.primed='false';}).finally(()=>{crowdPriming=false;});}
function syncSelectedCrowd(){const media=$('crowdAudio');if(!media?.getAttribute('src'))return;media.volume=clamp(selectedCrowdLevel());media.playbackRate=effectivePlaybackRate();media.preservesPitch=true;if(!selectedCrowdActive()){if(!crowdPriming&&!media.paused)media.pause();return;}if(media.readyState>=1&&Math.abs(media.currentTime-(t-marks.dream))>.35){try{media.currentTime=t-marks.dream;}catch{}}if(media.paused&&!crowdPlayPending&&!media.error){crowdPlayPending=true;media.play().catch(()=>{crowdLoadError=true;}).finally(()=>crowdPlayPending=false);}}
$('crowdAudio')?.addEventListener('error',()=>{crowdLoadError=true;});

function waitingForReflection(){return started&&where(t)===5&&t>=interactionTime&&!reflectionDone&&!finished;}
function musicExitProgress(){return musicExitAt?clamp((performance.now()-musicExitAt)/2000):0;}
function scoreEnvelope(){if(t<marks.musicOutStart)return ease(t/3);if(t<marks.musicReturn)return 1-ease((t-marks.musicOutStart)/(marks.outsidePhone-marks.musicOutStart));return ease((t-marks.musicReturn)/.015);}
function scoreTargetTime(){const raw=t>=marks.outsidePhone+.05?0+(t-marks.musicReturn):t,d=audio?._scoreBuffer?.duration||71.111111;return((raw%d)+d)%d;}
function scorePlayhead(){if(!audio)return 0;if(!audio._scoreSource)return audio._scoreLastOffset||0;const d=audio._scoreBuffer.duration;return(audio._scoreStartOffset+(audio.currentTime-audio._scoreStartClock)*audio._scoreClockRate)%d;}
function stopScore(){if(!audio?._scoreSource)return;audio._scoreLastOffset=scorePlayhead();audio._scoreSource.stop();audio._scoreSource.disconnect();audio._scoreSource=null;}
function startScore(offset){const rate=effectivePlaybackRate(),buffer=audio._rateBuffers?.[rate];if(!buffer)return;const source=audio.createBufferSource();source.buffer=buffer;source.playbackRate.value=1;source.loop=true;source.connect(audio._score);audio._scoreClockRate=rate;audio._scoreStartClock=audio.currentTime;audio._scoreStartOffset=offset;audio._scoreSource=source;source.start(audio.currentTime,offset/rate);}

function loadScore(){if(audio._scoreLoading||audio._scoreBuffer||musicBlocked)return;audio._scoreLoading=true;fetch($('scoreAudio').src).then(r=>{if(!r.ok)throw Error('Score load');return r.arrayBuffer();}).then(b=>audio.decodeAudioData(b)).then(buffer=>{audio._scoreBuffer=buffer;audio._scoreLoading=false;loadRateScores();syncMusic();}).catch(()=>{audio._scoreLoading=false;musicBlocked=true;$('scoreNote').textContent=EN?'Tap Music to retry playback.':'请点“配乐”重试播放';});}

function loadRateScores(){audio._rateBuffers={};const element=$('scoreAudio');for(const rate of [1.25,1.5625,1.875,2.5]){const src=element.dataset['rate'+String(rate).replace('.','')];if(!src)continue;fetch(src).then(r=>{if(!r.ok)throw Error('Rate score');return r.arrayBuffer();}).then(b=>audio.decodeAudioData(b)).then(buffer=>{audio._rateBuffers[rate]=buffer;if(effectivePlaybackRate()===rate){stopScore();syncMusic();}}).catch(()=>{});}}
function setPlaybackRate(rate){if(![1,1.25,1.5,2].includes(rate))return;stopScore();playbackRate=rate;syncMusic();window.dispatchEvent(new CustomEvent('filmratechange',{detail:rate}));}

function syncMusic(){if(!audio)return;const waiting=waitingForReflection(),exiting=musicExitAt>0&&musicExitProgress()<1,shouldPlay=started&&(playing||waiting||exiting)&&(!finished||exiting)&&musicEnabled&&!muted;if(!shouldPlay){stopScore();return;}if(!audio._scoreBuffer){loadScore();return;}const target=scoreTargetTime();if(!audio._scoreSource){startScore(target);return;}const d=audio._scoreBuffer.duration,difference=Math.abs(((scorePlayhead()-target+d*1.5)%d)-d/2);if(!waiting&&!exiting&&difference>.12){stopScore();startScore(target);}}
